window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-11491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκοτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra ε · nº geral 11491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐνεκότουν) irritar-se profundamente; indignar-se contra, dat. 〈ἔγκοτος1〉</p></section></article>\n<article id=\"entry-dgp-11492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκοτος1, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra ε · nº geral 11492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que guarda ressentimento; irado; rancoroso. 〈ἐν, κότος〉</p></section></article>\n<article id=\"entry-dgp-11493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκοτος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra ε · nº geral 11493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ressentimento profundo; indignação; rancor. 〈ἐν, κότος〉</p></section></article>\n<article id=\"entry-dgp-11494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra ε · nº geral 11494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor.2 ἐνέκραγον, part. ἐγκραγών, e perf. ἐγκέκραγα) gritar contra, dat., ἐπί e ac. 〈ἐν, κράζω〉</p></section></article>\n<article id=\"entry-dgp-11495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκραθείς</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra ε · nº geral 11495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. de ἐγκεράννυμι.</p></section></article>\n<article id=\"entry-dgp-11496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρασίχολος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra ε · nº geral 11496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">anchova. 〈ἐγκεράννυμι, χολή〉</p></section></article>\n<article id=\"entry-dgp-11497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκράτεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra ε · nº geral 11497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">domínio de si mesmo; temperança; moderação. 〈ἐγκρατής〉</p></section></article>\n<article id=\"entry-dgp-11498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρατέως</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra ε · nº geral 11498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐγκρατῶς.</p></section></article>\n<article id=\"entry-dgp-11499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρατεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra ε · nº geral 11499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dominar-se; ser senhor de si 2 crist. praticar abstinência; abster-se de, gen. ou ἀπό e gen. 〈ἐγκρατής〉</p></section></article>\n<article id=\"entry-dgp-11500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρατής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra ε · nº geral 11500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forte; vigoroso 2 senhor de, gen. 3 senhor de si mesmo; moderado; temperante em, gen. 〈ἐν, κράτος〉</p></section></article>\n<article id=\"entry-dgp-11501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρατῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra ε · nº geral 11501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com temperança; com moderação.</p></section></article>\n<article id=\"entry-dgp-11502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra ε · nº geral 11502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 triar; escolher 2 admitir após avaliação ou seleção 3 aceitar; aprovar algo. 〈ἐν, κρίνω〉</p></section></article>\n<article id=\"entry-dgp-11503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκρισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra ε · nº geral 11503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exame; seleção 2 admissão; aprovação. 〈ἐγκρίνω〉</p></section></article>\n<article id=\"entry-dgp-11504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκριτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra ε · nº geral 11504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἐγκρίνω.</p></section></article>\n<article id=\"entry-dgp-11505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκροτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra ε · nº geral 11505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 golpear; bater ruidosamente (no solo ao dançar) ♦ méd. 2 golpear-se. 〈ἐν, κροτέω〉</p></section></article>\n<article id=\"entry-dgp-11506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra ε · nº geral 11506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐγκρύψω, aor. ἐνέκρυψα; perf. pas. ἐγκέκρυμμαι) 1 ocultar em, dat. ou ἐν e dat., εἰς e ac. ♦ méd. 2 esconder-se em, dat. 〈ἐν, κρύπτω〉</p></section></article>\n<article id=\"entry-dgp-11507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκρυφίας ἄρτος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra ε · nº geral 11507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pão cozido (escondido) sob a cinza. 〈ἐγκρύπτω〉</p></section></article>\n<article id=\"entry-dgp-11508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκτάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 269 na letra ε · nº geral 11508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adquirir ou possuir propriedade num país estrangeiro, ἐν e dat.; οἱ ἐγκεκτημένοι os proprietários estrangeiros que não são do demos. 〈ἐν, κτάομαι〉</p></section></article>\n<article id=\"entry-dgp-11509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκτασις</h1><div class=\"entry-meta\"><span>DGP · ordem 270 na letra ε · nº geral 11509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἔγκτησις.</p></section></article>\n<article id=\"entry-dgp-11510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 271 na letra ε · nº geral 11510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 direito de adquirir propriedade em país estrangeiro 2 aquisição; propriedade. 〈ἐγκτάομαι〉</p></section></article>\n<article id=\"entry-dgp-11511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 272 na letra ε · nº geral 11511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. part. ἐγκτίσας) fundar em, dat. ou ἐν e dat.</p></section></article>\n<article id=\"entry-dgp-11512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκύκλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 273 na letra ε · nº geral 11512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 circular: ἐγκύκλιος κίνησις movimento circular 2 ordinário; periódico; diário: ἐγκύκλιος λειτουργία dem. cargo periódico 3 que forma um círculo completo: ἡ ἐγκύκλιος παιδεία, τὰ ἐγκύκλια παιδεύματα o ciclo completo dos estudos ♦ τὰ ἐγκύκλια 4 as ocupações diárias 5 o ciclo completo dos estudos. 〈ἐν, κύκλος〉</p></section></article>\n<article id=\"entry-dgp-11513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκυκλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 274 na letra ε · nº geral 11513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 circular ♦ τὸ ἔγκυκλον 2 roupa feminina. 〈ἐν, κύκλος〉</p></section></article>\n<article id=\"entry-dgp-11514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκυκλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 275 na letra ε · nº geral 11514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mover em círculo; passear (o olhar) ao redor 2 circundar; rodear 3 fazer a ronda; rondar ♦ méd. 4 fazer a volta; rodear. 〈ἐν, κυκλόω〉</p></section></article>\n<article id=\"entry-dgp-11515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκυλίω</h1><div class=\"entry-meta\"><span>DGP · ordem 276 na letra ε · nº geral 11515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐγκυλίσω) 1 enrolar em; envolver algo, ac., em, εἰς e ac. ♦ méd. 2 rolar-se em; encontrar-se envolvido em; entregar-se a, dat. ou ἐν e dat., εἰς e ac. 〈ἐν, κυλίω〉</p></section></article>\n<article id=\"entry-dgp-11516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκύμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 277 na letra ε · nº geral 11516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 fem., grávida (mulher); prenhe (fêmea); fecunda; fértil; germinante (semente) 2 masc. e fem., gordo; cheio de, gen. 〈ἐν, κυέω〉</p></section></article>\n<article id=\"entry-dgp-11517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγκυος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 278 na letra ε · nº geral 11517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard.= ἐγκύμων.</p></section></article>\n<article id=\"entry-dgp-11518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 279 na letra ε · nº geral 11518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. ἐγκέκυφα) 1 pender para ou em; inclinar-se para, εἰς e ac. 2 perf. ser inclinado. 〈ἐν, κύπτω〉</p></section></article>\n<article id=\"entry-dgp-11519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκυρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 280 na letra ε · nº geral 11519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνεκύρησα) 1 encontrar-se em ou com, dat. 2 topar com alguém, gen. ou dat. 〈ἐν, κυρέω〉</p></section></article>\n<article id=\"entry-dgp-11520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκύρω</h1><div class=\"entry-meta\"><span>DGP · ordem 281 na letra ε · nº geral 11520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνέκυρσα) = ἐγκυρέω.</p></section></article>\n<article id=\"entry-dgp-11521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκωμιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 282 na letra ε · nº geral 11521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐνεκωμίαζον, fut. ἐγκωμιάσω e ἐγκωμιάσομαι, aor. ἐνεκωμίασα, perf. ἐγκεκωμίακα; pas. aor. ἐνεκωμιάσθην, perf. ἐγκεκωμίασμαι) louvar; elogiar; celebrar alguém, ac., por algo, ac. ou κατά e ac., περί e ac., ἐπί e dat. 〈ἐγκώμιον〉</p></section></article>\n<article id=\"entry-dgp-11522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκωμιαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra ε · nº geral 11522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">encomiasta; laudador. 〈ἐγκωμιάζω〉</p></section></article>\n<article id=\"entry-dgp-11523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκωμιαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra ε · nº geral 11523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">encomiástico; elogioso. 〈ἐγκω­μιάζω〉</p></section></article>\n<article id=\"entry-dgp-11524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγκώμιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra ε · nº geral 11524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">encômio; elogio. 〈ἐν, κῶμος〉</p></section></article>\n<article id=\"entry-dgp-11525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγλυμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra ε · nº geral 11525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. γλύφω.</p></section></article>\n<article id=\"entry-dgp-11526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγνωκα, ἔγνων, ἐγνώσθην, ἔγνωσμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra ε · nº geral 11526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-11527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρεμάχας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra ε · nº geral 11527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só ac. ἐγρεμάχαν (masc.) que incita ao combate; belicoso. 〈ἐγείρω, μάχη〉</p></section></article>\n<article id=\"entry-dgp-11528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρεμάχη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra ε · nº geral 11528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) belicosa, epít. de Palas.</p></section></article>\n<article id=\"entry-dgp-11529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγρεο</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra ε · nº geral 11529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper., ἐγρέσθαι inf., formas de aor.2 méd. ép. de ἐγείρω.</p></section></article>\n<article id=\"entry-dgp-11530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρήγορα</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra ε · nº geral 11530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf.2 de ἐγείρω.</p></section></article>\n<article id=\"entry-dgp-11531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγοράω</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra ε · nº geral 11531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. ép. ἐγρηγορόων) estar desperto.</p></section></article>\n<article id=\"entry-dgp-11532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγόρθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra ε · nº geral 11532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf., ἐγρηγόρθασι 3ª pl. ind., ἐγρήγορθε 2ª sing. imper., formas de perf. ép. de ἐγείρω.</p></section></article>\n<article id=\"entry-dgp-11533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγορότως</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra ε · nº geral 11533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. velando; com vigilância. 〈ἐγρηγορώς〉</p></section></article>\n<article id=\"entry-dgp-11534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγορόων</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra ε · nº geral 11534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐγρηγοράω.</p></section></article>\n<article id=\"entry-dgp-11535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρήγορσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra ε · nº geral 11535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estado de vigília. 〈ἐγρήγορα〉</p></section></article>\n<article id=\"entry-dgp-11536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγορτί</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra ε · nº geral 11536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em vigília. 〈ἐγρήγορα〉</p></section></article>\n<article id=\"entry-dgp-11537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγορώς, υῖα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra ε · nº geral 11537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pf.2 de ἐγείρω.</p></section></article>\n<article id=\"entry-dgp-11538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρηγόρως</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra ε · nº geral 11538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = ἐγρηγορότως.</p></section></article>\n<article id=\"entry-dgp-11539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγρήσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra ε · nº geral 11539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) estar de vigília; velar. 〈ἐγρήγορα〉</p></section></article>\n<article id=\"entry-dgp-11540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγροιτο</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra ε · nº geral 11540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª opt., ἐγρόμενος part., ἐγρόμην 1ª sing. ind., formas de aor.2 méd. ép. de ἐγείρω.</p></section></article>\n<article id=\"entry-dgp-11541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra ε · nº geral 11541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. méd. 2ª e 3ª sing. ἐγχανεῖ, ἐγχανεῖται; aor.2 opt. 3ª sing. ἐγχάνοι, part. ἐγχανών) 1 olhar boquiaberto; ficar pasmo diante de, πρός e ac. 2 rir; zombar de, dat. 〈ἐν, χαίνω〉</p></section></article>\n<article id=\"entry-dgp-11542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχαλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra ε · nº geral 11542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relaxar; soltar. 〈ἐν, χαλάω〉</p></section></article>\n<article id=\"entry-dgp-11543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχαλινόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra ε · nº geral 11543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr o freio em; embridar; refrear 2 ter a forma de freio. 〈ἐν, χαλινόω〉</p></section></article>\n<article id=\"entry-dgp-11544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχάραξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra ε · nº geral 11544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de entalhar, de escarificar. 〈ἐγχαράσσω〉</p></section></article>\n<article id=\"entry-dgp-11545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχαράσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra ε · nº geral 11545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gravar; esculpir; entalhar em, εἰς e ac. ou κατά e gen. 〈ἐν, χαράσσω〉</p></section></article>\n<article id=\"entry-dgp-11546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχέαι, ἐγχέας</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra ε · nº geral 11546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. e part. aor. de ἐγχέω.</p></section></article>\n<article id=\"entry-dgp-11547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχείη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra ε · nº geral 11547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lança. 〈ἔγχος〉</p></section></article>\n<article id=\"entry-dgp-11548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχείῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra ε · nº geral 11548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. subj. pres. ép. de ἐγχέω.</p></section></article>\n<article id=\"entry-dgp-11549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχειρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra ε · nº geral 11549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr a mão em; empreender, dat. 2 pôr a mão sobre; atacar, dat. 3 dispensar cuidados com; tratar (doente, doença), dat. 4 tratar; discutir (assunto). 〈ἐν, χείρ〉</p></section></article>\n<article id=\"entry-dgp-11550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχείρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra ε · nº geral 11550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">empresa contra; ataque; ato de violência. 〈ἐγχειρέω〉</p></section></article>\n<article id=\"entry-dgp-11551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχείρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra ε · nº geral 11551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">empreendimento; empresa; operação. 〈ἐγχειρέω〉</p></section></article>\n<article id=\"entry-dgp-11552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχειρητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra ε · nº geral 11552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἐγχειρέω.</p></section></article>\n<article id=\"entry-dgp-11553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχειρητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra ε · nº geral 11553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">empreendedor. 〈ἐγχειρέω〉</p></section></article>\n<article id=\"entry-dgp-11554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχειρίδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra ε · nº geral 11554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mantido nas mãos ♦ τὸ ἐγχειρίδιον 2 punho; cabo 3 punhal 4 bíbl. ferramenta 5 manual (livro). 〈ἐν, χείρ〉</p></section></article>\n<article id=\"entry-dgp-11555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχειρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra ε · nº geral 11555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. ἐγχειριῶ, aor. ἐνεχείρισα, perf. ἐγκεχείρικα) 1 pôr na mão de; confiar; entregar algo ou alguém, ac., para alguém, dat. ♦ méd. 2 pegar em mãos; assumir; empreender. 〈ἐν, χείρ〉</p></section></article>\n<article id=\"entry-dgp-11556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχειρίθετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra ε · nº geral 11556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colocado nas mãos de alguém; entregue. 〈ἐν, χείρ, τίθημι〉</p></section></article>\n<article id=\"entry-dgp-11557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχελυς, υος</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra ε · nº geral 11557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. át. ἐγχέλεις (ἡ) enguia.</p></section></article>\n<article id=\"entry-dgp-11558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχελυωπός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra ε · nº geral 11558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com olhos de enguia. 〈ἔγχελυς, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-11559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχεσίμωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra ε · nº geral 11559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem a lança na mão; que combate com lança; de lança furiosa. 〈ἔγχος, μωρός〉</p></section></article>\n<article id=\"entry-dgp-11560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχέσπαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra ε · nº geral 11560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que brande a lança. 〈ἔγχος, πάλλω〉</p></section></article>\n<article id=\"entry-dgp-11561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχεῦτα</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra ε · nº geral 11561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. sing. part. pres. dór. de ἐγχέω.</p></section></article>\n<article id=\"entry-dgp-11562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχέω</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra ε · nº geral 11562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνέχεα) 1 servir (bebida); versar; verter líquido, ac., em, ac. ou εἰς e ac. 2 verter em honra de; brindar à saúde de, gen. ou dat. ♦ méd. 3 verter para si. 〈ἐν, χέω〉</p></section></article>\n<article id=\"entry-dgp-11563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχλίω</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra ε · nº geral 11563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) tratar de modo insolente; insultar, dat. 〈ἐν, χλίω〉</p></section></article>\n<article id=\"entry-dgp-11564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχορεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra ε · nº geral 11564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter prazer em; divertir-se com, dat. 〈ἐν, χορεύω〉</p></section></article>\n<article id=\"entry-dgp-11565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra ε · nº geral 11565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lança; dardo 2 espada; arma.</p></section></article>\n<article id=\"entry-dgp-11566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχουσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra ε · nº geral 11566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = ἄγχουσα.</p></section></article>\n<article id=\"entry-dgp-11567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχραύω</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra ε · nº geral 11567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. ἐνέχραυε) dirigir golpes sobre; golpear, ἐς ou πρός e ac. 〈ἐν, χραύω〉</p></section></article>\n<article id=\"entry-dgp-11568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχράω</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra ε · nº geral 11568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. pas. ἐγκεχρημένος) dirigir ataque contra; atacar, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-11569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχρεμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra ε · nº geral 11569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escarro. 〈ἐγχρέμπτομαι〉</p></section></article>\n<article id=\"entry-dgp-11570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχρέμπτομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra ε · nº geral 11570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. ἐνεχρέμπτετο) escarrar.</p></section></article>\n<article id=\"entry-dgp-11571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχρῄζω</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra ε · nº geral 11571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 ter necessidade de, gen. 2 ser necessário; ser indispensável ♦ τὰ ἐγχρῄζοντα 3 o necessário. 〈ἐν, χρῄζω〉</p></section></article>\n<article id=\"entry-dgp-11572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχρίμπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra ε · nº geral 11572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor. ἐνέχριμψα) 1 empurrar; encaixar em; ajustar a 2 fazer abordar; ancorar (barco) em, dat. 3 chocar-se contra; lançar-se sobre; apoderar-se de, dat. 4 aproximar-se de; abordar 5 unir-se a alguém, dat. ♦ méd. 6 chocar-se contra; penetrar em 7 jogar-se sobre; (doença) atacar 8 perseguir (em caçada), dat. 〈ἐν, χρίμπτω〉</p></section></article>\n<article id=\"entry-dgp-11573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχρισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra ε · nº geral 11573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 unção 2 picada; mordida. 〈ἐγχρίω〉</p></section></article>\n<article id=\"entry-dgp-11574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχριστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra ε · nº geral 11574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que serve para ungir, para untar. 〈ἐγχρίω〉</p></section></article>\n<article id=\"entry-dgp-11575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχρίω</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra ε · nº geral 11575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 untar; ungir 2 fazer penetrar em; picar ♦ méd. 3 untar-se de, gen. 〈ἐν, χρίω〉</p></section></article>\n<article id=\"entry-dgp-11576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχρονίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra ε · nº geral 11576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐνεχρόνιζον, fut. ἐγχρονίσω, át. ἐγχρονιῶ etc.) 1 passar o tempo em, dat. ou ἐν e dat. 2 demorar 3 tornar-se crônico ♦ pas. 4 tornar-se crônico. 〈ἐν, χρόνος〉</p></section></article>\n<article id=\"entry-dgp-11577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra ε · nº geral 11577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐγχέω.</p></section></article>\n<article id=\"entry-dgp-11578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra ε · nº geral 11578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">injeção. 〈ἐγχέω〉</p></section></article>\n<article id=\"entry-dgp-11579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra ε · nº geral 11579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar espaço ou tempo para; permitir 2 impes. ἐγχωρεῖ há lugar para; há tempo para; é possível; é permitido, inf.: ἔτι ἐγχωρεῖ ainda há tempo, ainda é possível. 〈ἐν, χωρέω〉</p></section></article>\n<article id=\"entry-dgp-11580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγχώριος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra ε · nº geral 11580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 situado no país 2 habitante do país; nativo 3 que é do país; local 4 do campo; rústico. 〈ἐν, χώρα〉</p></section></article>\n<article id=\"entry-dgp-11581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγχωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra ε · nº geral 11581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐγχώριος.</p></section></article>\n<article id=\"entry-dgp-11582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγώ</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra ε · nº geral 11582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(sing. nom. ἐγώ, gen. ἐμοῦ, μου, dat. ἐμοί, μοι, ac. ἐμέ, με; pl. nom. ἡμεῖς, gen. ἡμῶν, dat. ἡμῖν, ac. ἡμᾶς; dual nom. e ac. νώ, gen. e dat. νῷν) pron. pes. de 1ª pes. eu, pl. nós; empregos: 1 nom. usado em ger. para enfatizar o sujeito ou, nas respostas, ger. na forma enfática ἔγωγε, para expressar afirmação: ἐπεὶ ὑμεῖς ἐμοὶ οὐ θέλετε πείθεσθαι, ἐγὼ σὺν ὑμῖν ἕψομαι xen. já que a mim vós não quereis obedecer, eu, por mim, convosco seguirei, ἦ καὶ τοῦτο ἀκήκοας; – ἔγωγε plat. por certo também ouviste isso? – Eu, pelo menos, sim! 2 acompanhado de demonstr. ou de art.: ὅδ᾽ αὐτὸς ἐγώ hom. eu mesmo aqui presente, δοκέει δέ μοι ὧδε καὶ αὐτῷ λώϊον ἔσσεσθαι hom. também a mim mesmo parece que será melhor assim 3 pl. de modéstia, ref. a uma só pes.: ἀλλ᾽ ἡ μὲν ἡμῶν μοῖρ᾽, ὅποιπερ εἶσ᾽, ἴτω sóf. mas que o nosso [= meu] destino siga para onde justamente deve ir.</p></section></article>\n<article id=\"entry-dgp-11583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγωγε</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra ε · nº geral 11583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só nom. e dat. ἔμοιγε) forma enfática de ἐγώ.</p></section></article>\n<article id=\"entry-dgp-11584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγᾦδα</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra ε · nº geral 11584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ἐγὼ οἶδα.</p></section></article>\n<article id=\"entry-dgp-11585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγᾦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra ε · nº geral 11585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ἐγὼ οἶμαι.</p></section></article>\n<article id=\"entry-dgp-11586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐγών</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra ε · nº geral 11586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = ἐγώ.</p></section></article>\n<article id=\"entry-dgp-11587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔγωνγα</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra ε · nº geral 11587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἔγωγε.</p></section></article>\n<article id=\"entry-dgp-11588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔδαε, ἐδάην</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra ε · nº geral 11588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. δαῆναι.</p></section></article>\n<article id=\"entry-dgp-11589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔδακον</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra ε · nº geral 11589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de δάκνω.</p></section></article>\n<article id=\"entry-dgp-11590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐδάμασσα</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra ε · nº geral 11590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. poét. de δαμάζω.</p></section></article>\n";
